PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, auth0_sub TEXT NOT NULL UNIQUE, email TEXT NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','member')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE ai_provider_keys (workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE, ciphertext TEXT NOT NULL, hint TEXT NOT NULL, model TEXT NOT NULL, verified_at TEXT NOT NULL, updated_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE companies (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, domain TEXT NOT NULL, name TEXT NOT NULL, arr INTEGER NOT NULL DEFAULT 0 CHECK(arr>=0), owner TEXT NOT NULL DEFAULT '', renewal TEXT NOT NULL DEFAULT '', health INTEGER NOT NULL DEFAULT 75 CHECK(health BETWEEN 0 AND 100), UNIQUE(workspace_id,domain), UNIQUE(workspace_id,id));
CREATE TABLE sources (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('csv','manual','sample')), created_at TEXT NOT NULL, UNIQUE(workspace_id,id));
CREATE TABLE documents (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, company_id TEXT NOT NULL, source_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,company_id) REFERENCES companies(workspace_id,id), FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE chunks (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, document_id TEXT NOT NULL, ordinal INTEGER NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready','failed')), error_code TEXT, UNIQUE(workspace_id,id), UNIQUE(document_id,ordinal), FOREIGN KEY(workspace_id,document_id) REFERENCES documents(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE chunk_embeddings (id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, chunk_id TEXT NOT NULL UNIQUE, model TEXT NOT NULL, embedding F32_BLOB(1536) NOT NULL, FOREIGN KEY(workspace_id,chunk_id) REFERENCES chunks(workspace_id,id) ON DELETE CASCADE);
CREATE INDEX chunk_vector_idx ON chunk_embeddings(libsql_vector_idx(embedding));
CREATE INDEX chunks_workspace_status ON chunks(workspace_id,status);
CREATE INDEX documents_workspace ON documents(workspace_id,created_at);
CREATE VIRTUAL TABLE chunks_fts USING fts5(body, content='chunks', content_rowid='rowid');
CREATE TRIGGER chunks_ai AFTER INSERT ON chunks BEGIN INSERT INTO chunks_fts(rowid,body) VALUES(new.rowid,new.body); END;
CREATE TRIGGER chunks_ad AFTER DELETE ON chunks BEGIN INSERT INTO chunks_fts(chunks_fts,rowid,body) VALUES('delete',old.rowid,old.body); END;
CREATE TRIGGER chunks_au AFTER UPDATE OF body ON chunks BEGIN INSERT INTO chunks_fts(chunks_fts,rowid,body) VALUES('delete',old.rowid,old.body); INSERT INTO chunks_fts(rowid,body) VALUES(new.rowid,new.body); END;
CREATE TABLE signals (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, company_id TEXT NOT NULL, chunk_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('risk','expansion','competitor')), title TEXT NOT NULL, detail TEXT NOT NULL, quote TEXT NOT NULL, confidence INTEGER NOT NULL CHECK(confidence BETWEEN 0 AND 100), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), created_at TEXT NOT NULL, UNIQUE(workspace_id,chunk_id,kind,title), FOREIGN KEY(workspace_id,company_id) REFERENCES companies(workspace_id,id), FOREIGN KEY(workspace_id,chunk_id) REFERENCES chunks(workspace_id,id) ON DELETE CASCADE);
CREATE INDEX signals_workspace ON signals(workspace_id,status,created_at);
CREATE TABLE competitors (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, company_id TEXT NOT NULL, chunk_id TEXT NOT NULL, name TEXT NOT NULL, quote TEXT NOT NULL, UNIQUE(workspace_id,chunk_id,name), FOREIGN KEY(workspace_id,company_id) REFERENCES companies(workspace_id,id), FOREIGN KEY(workspace_id,chunk_id) REFERENCES chunks(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE chat_threads (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id,id));
CREATE TABLE chat_messages (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, thread_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','assistant')), body TEXT NOT NULL, citations TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,thread_id) REFERENCES chat_threads(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE tool_calls (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE saved_queries (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, query TEXT NOT NULL, share_token TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE usage_events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id), operation TEXT NOT NULL, model TEXT NOT NULL, tokens INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX usage_workspace ON usage_events(workspace_id,created_at);
CREATE TABLE rate_limits (bucket TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE workspace_jobs (workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE, lease_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
